#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2317  # library: "$e[" is no array; unused helpers stay
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up what GitHub Actions needs to deploy the preview through the
# jumphost: the deploy key, the user deploy (bootstrap.yml), the host keys and
# the secrets of the GitHub environment home. Run it from the home network
# (it scans einrad-server and caddy), with gh logged in:
#
#   deploy/setup-wizard.sh
#
# Every stage can be skipped when it's already done. The jumphost's real name
# only goes from your input into the secret HOME_JUMPHOST: the known_hosts
# lines name it `jump` (as deploy/inventory.yml does), and nothing is written
# to the repository. The private key only lives in a temp directory, which is
# removed at the end.

REPO="${REPO:-Snapstromegon/einrad-server}"
GH_ENV=home
# The jumphost forwards to exactly these names (permitopen, bootstrap.yml).
TARGETS=(einrad-server caddy)
# Never read or write a .env: nothing is remembered between runs.
ENV_FILE=/dev/null

gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# set_env_secret NAME VALUE sets a secret of the GitHub environment GH_ENV;
# the library's set_secret only sets repository secrets. The value goes
# through stdin, never the command line.
set_env_secret() {
  local name="$1" value="$2"
  if printf '%s' "$value" | gh secret set "$name" --env "$GH_ENV" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s secret %s in environment %s\n' "$GREEN" "$RESET" "$name" "$GH_ENV"
  else
    SKIPPED+=("secret $name in environment $GH_ENV (run the wizard again)")
    warn "couldn't set $name"
  fi
}

# keyscan NAME HOST [PORT] prints HOST's host keys as known_hosts lines for
# NAME, the name ssh looks them up by.
keyscan() {
  { ssh-keyscan -T 10 -p "${3:-22}" -- "$2" 2>/dev/null || true; } |
    awk -v name="$1" '!/^#/ && NF >= 3 { $1 = name; print }'
}

run_wizard() {

TOTAL_STAGES=7
cd "$(dirname "$0")/.."

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
KEY=""  # the new deploy key's private key file, in WORK
JUMPHOST="" JUMPHOST_PORT="" KNOWN_HOSTS=""

banner "Deploy setup: GitHub Actions → jump → einrad-server, caddy"
note "Nothing is remembered between runs: skip what's done already."

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Deploy key"
say "GitHub Actions logs in as deploy with an ed25519 key. A new one is"
say "created in $WORK, outside the repository, and deleted at the end."
if confirm "Create a new deploy key?"; then
  KEY="$WORK/einrad-deploy"
  ssh-keygen -q -t ed25519 -N '' -C einrad-deploy -f "$KEY"
  printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$(cut -d' ' -f1,2 "$KEY.pub")"
else
  note "Without a new key, the bootstrap, HOME_SSH_KEY and the check are skipped."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Bootstrap the user deploy"
if [[ -z "$KEY" ]]; then
  note "No key, skipped."
else
  say "deploy/bootstrap.yml creates deploy on jump, einrad-server and caddy"
  say "and replaces deploy's authorized_keys with the deploy key (and yours)."
  step "It logs in with your account via the aliases jump, einrad-server and"
  step "caddy from your ~/.ssh/config and asks for your sudo password (-K)."
  cp "$KEY.pub" "$WORK/deploy_keys.pub"
  note "To also deploy as deploy by hand, add your own public key; a key of"
  note "yours that deploy had before is removed otherwise."
  ask OWN_PUBKEY "Your public key file (Enter: none):"
  OWN_PUBKEY="${OWN_PUBKEY/#\~/$HOME}"
  if [[ -n "$OWN_PUBKEY" && -f "$OWN_PUBKEY" ]]; then
    cat "$OWN_PUBKEY" >> "$WORK/deploy_keys.pub"
  elif [[ -n "$OWN_PUBKEY" ]]; then
    warn "$OWN_PUBKEY doesn't exist; only the deploy key goes in"
  fi
  bootstrap=(ansible-playbook -i deploy/inventory.yml deploy/bootstrap.yml -K
    -e "deploy_public_key=$WORK/deploy_keys.pub")
  note "${bootstrap[*]}"
  if confirm "Run it now? (No if it ran with this key already)"; then
    if ! "${bootstrap[@]}"; then
      warn "bootstrap.yml failed"
      SKIPPED+=("bootstrap.yml failed: fix it and run the wizard again")
    fi
  fi
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Jumphost and host keys"
say "CI reaches einrad-server and caddy through the jumphost. Its name and"
say "port only go into the secrets HOME_JUMPHOST and HOME_JUMPHOST_PORT."
while :; do
  ask JUMPHOST "Jumphost host name as seen from the internet (Enter: skip):"
  [[ -z "$JUMPHOST" || "$JUMPHOST" =~ ^[A-Za-z0-9]([A-Za-z0-9.:-]*[A-Za-z0-9])?$ ]] && break
  warn "that isn't a host name or address"
done
if [[ -n "$JUMPHOST" ]]; then
  while :; do
    ask JUMPHOST_PORT "Its SSH port (Enter: 22):"
    JUMPHOST_PORT="${JUMPHOST_PORT:-22}"
    [[ "$JUMPHOST_PORT" =~ ^[0-9]{1,5}$ ]] && (( 10#$JUMPHOST_PORT >= 1 && 10#$JUMPHOST_PORT <= 65535 )) && break
    warn "a port is a number from 1 to 65535"
  done
  say "HOME_KNOWN_HOSTS holds the host keys of the jumphost (as jump, CI's"
  say "HostKeyAlias) and of einrad-server and caddy (the names CI jumps to)."
  note "einrad-server and caddy are scanned at the HostName your ~/.ssh/config"
  note "gives them, so run this from the home network."
  if confirm "Scan the host keys now? (No if HOME_KNOWN_HOSTS is set already)"; then
    found=1
    keyscan jump "$JUMPHOST" "$JUMPHOST_PORT" > "$WORK/known_hosts"
    grep -q '^jump ' "$WORK/known_hosts" || { warn "no host keys from the jumphost"; found=0; }
    # Port 22, not your config's Port: the jumphost only forwards to :22.
    for target in "${TARGETS[@]}"; do
      host=$(ssh -G "$target" 2>/dev/null | awk '$1 == "hostname" { print $2; exit }' || true)
      keyscan "$target" "${host:-$target}" >> "$WORK/known_hosts"
      grep -q "^$target " "$WORK/known_hosts" || { warn "no host keys from $target (${host:-$target})"; found=0; }
    done
    if (( found )); then
      ssh-keygen -lf "$WORK/known_hosts" | sed 's/^/    /'
      step "Compare them with the hosts' own, on each host:"
      note "  for f in /etc/ssh/ssh_host_*_key.pub; do ssh-keygen -lf \"\$f\"; done"
      if confirm "Do the fingerprints match?"; then
        KNOWN_HOSTS=$(cat "$WORK/known_hosts")
      fi
    fi
    [[ -n "$KNOWN_HOSTS" ]] || SKIPPED+=("HOME_KNOWN_HOSTS: no host keys (run the wizard again)")
  fi
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub environment $GH_ENV and its secrets"
if ! gh_ready; then
  warn "gh is missing or not logged in (gh auth login)"
  SKIPPED+=("environment $GH_ENV and its secrets: run the wizard again with gh")
else
  if gh api "repos/$REPO/environments/$GH_ENV" >/dev/null 2>&1; then
    note "The environment $GH_ENV exists."
  elif confirm "Create the environment $GH_ENV (no reviewers) in $REPO?"; then
    if gh api --method PUT "repos/$REPO/environments/$GH_ENV" >/dev/null; then
      printf '  %s✓ created%s environment %s\n' "$GREEN" "$RESET" "$GH_ENV"
    else
      warn "couldn't create the environment"
    fi
  fi
  existing=$(gh secret list --env "$GH_ENV" --repo "$REPO" --json name --jq '.[].name' 2>/dev/null || true)
  # Only the values from this run; the others stay as they are.
  secrets=()
  [[ -n "$KEY" ]] && secrets+=(HOME_SSH_KEY)
  [[ -n "$KNOWN_HOSTS" ]] && secrets+=(HOME_KNOWN_HOSTS)
  [[ -n "$JUMPHOST" ]] && secrets+=(HOME_JUMPHOST HOME_JUMPHOST_PORT)
  (( ${#secrets[@]} )) || note "No values from this run, nothing to set."
  for name in ${secrets[@]+"${secrets[@]}"}; do
    if grep -qx "$name" <<< "$existing" && ! confirm "$name is set already. Replace it?"; then
      continue
    fi
    case "$name" in
      # OpenSSH rejects a key file without its final newline.
      HOME_SSH_KEY) set_env_secret "$name" "$(cat "$KEY")"$'\n' ;;
      HOME_KNOWN_HOSTS) set_env_secret "$name" "$KNOWN_HOSTS" ;;
      HOME_JUMPHOST) set_env_secret "$name" "$JUMPHOST" ;;
      HOME_JUMPHOST_PORT) set_env_secret "$name" "$JUMPHOST_PORT" ;;
    esac
  done
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Check the connection"
if [[ -z "$KEY" || -z "$JUMPHOST" ]]; then
  note "Needs the key and the jumphost from this run, skipped."
else
  say "Logs in like CI: as deploy with the deploy key, through jump to"
  say "einrad-server and caddy, without your ~/.ssh/config."
  checking=yes
  if [[ -z "$KNOWN_HOSTS" ]]; then
    warn "no scanned host keys: they're accepted unchecked"
    checking=accept-new
    : > "$WORK/known_hosts"
  fi
  # In WORK, not the repository: it names the jumphost.
  cat > "$WORK/ssh_config" <<CONFIG
Host jump
  HostName $JUMPHOST
  Port $JUMPHOST_PORT
  HostKeyAlias jump
Host ${TARGETS[*]}
  ProxyJump jump
Host *
  User deploy
  IdentityFile "$KEY"
  IdentitiesOnly yes
  UserKnownHostsFile "$WORK/known_hosts"
  StrictHostKeyChecking $checking
  BatchMode yes
  ConnectTimeout 15
CONFIG
  if confirm "Connect now?"; then
    for target in "${TARGETS[@]}"; do
      if ssh -F "$WORK/ssh_config" "$target" true; then
        printf '  %s✓%s deploy@%s through jump\n' "$GREEN" "$RESET" "$target"
      else
        warn "deploy@$target through jump failed"
        SKIPPED+=("connection to $target failed: check bootstrap.yml and the host keys")
      fi
    done
  fi
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Authelia in front of Mailpit"
say "mail.einrad-server.home.hoeser.dev uses \`import authelia\` on caddy, and"
say "Authelia only lets you in if its access_control covers the domain."
step "Look at the rules on caddy (Authelia's configuration.yml, e.g. in /etc/authelia):"
note "  ssh caddy 'sudo grep -rn -A 30 \"^access_control:\" /etc/authelia'"
step "It's covered by a rule whose domain is mail.einrad-server.home.hoeser.dev"
step "or a wildcard like *.home.hoeser.dev, before any rule that denies it."
step "If not, add this to access_control.rules, above any deny rule:"
note "    - domain: 'mail.einrad-server.home.hoeser.dev'"
note "      policy: 'two_factor'   # or what monitoring.home.hoeser.dev uses"
step "Then restart Authelia, e.g. sudo systemctl restart authelia."
pause "Press Enter when it's covered"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Delete the local private key"
if [[ -n "$KEY" ]]; then
  say "CI only needs the key in HOME_SSH_KEY; the local copy in $WORK goes."
  if [[ " ${WRITTEN_SECRET[*]-} " != *" HOME_SSH_KEY "* ]]; then
    warn "HOME_SSH_KEY wasn't set in this run: without the key, the next run"
    warn "needs a new one and the bootstrap again."
  fi
  if confirm "Delete it now?"; then
    rm -rf "$WORK"
    printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$WORK"
  else
    trap - EXIT
    warn "kept $WORK: delete it yourself (rm -rf $WORK)"
    SKIPPED+=("delete $WORK")
  fi
else
  note "No local key, nothing to delete."
fi
pause

finish
}

run_wizard "$@"; exit
